<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'UUID Generator','description'=>'Generate cryptographically strong random UUID v4 identifiers locally.','url'=>'https://smarttoolz.in/tools/uuid-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>UUID Generator</h1><p>Generate random UUID v4 identifiers instantly.</p><button id="gen">Generate UUID</button><div id="out">Click Generate UUID.</div><button id="copy">Copy</button></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool button{margin:5px;padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool #out{margin:16px 0;padding:18px;background:#f6f7fb;border-radius:12px;font:18px monospace;word-break:break-all}</style><script>const o=document.getElementById('out');document.getElementById('gen').onclick=()=>o.textContent=crypto.randomUUID();document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.textContent)</script><?php smarttoolz_tool_page_end(); ?>